public class METSalesPriceComponents_Return extends METSalesPriceComponents
{ 
}

Method.Source:
/// <summary>
/// Query ranges
/// </summary>
/// <param name = "qbdsSalesLine">QueryBuildDataSource</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_metSalesTable">METSalesTable</param>
public void queryRange(QueryBuildDataSource qbdsSalesLine, SalesLine _salesLine, METSalesTable _metSalesTable)
{
    METSalesLine metSalesLine = _salesLine.metSalesLine();
    METOriginalInvoice   originalInvoice;
    QueryBuildDataSource qbdsCustInvoiceTrans;

    if (metSalesLine.InvoiceNumber || _metSalesTable.OriginalSalesId)
    {
        qbdsCustInvoiceTrans = qbdsSalesLine.addDataSource(tableNum(CustInvoiceTrans));
        qbdsCustInvoiceTrans.joinMode(JoinMode::InnerJoin);
        qbdsCustInvoiceTrans.addLink(fieldNum(SalesLine, InventTransId), fieldNum(CustInvoiceTrans, InventTransId));
        if (_metSalesTable.ClaimSalesId)
        {
            qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, InvoiceId)).value(metSalesLine.InvoiceNumber);
            qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, SalesId)).value(_metSalesTable.ClaimSalesId);
        }
        else if (_metSalesTable.OriginalSalesId)
        {
            qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, SalesId)).value(_metSalesTable.OriginalSalesId);
        }

        if (metSalesLine.InvoiceLineNumber)
        {
            qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, LineNum)).value(queryValue(metSalesLine.InvoiceLineNumber));
        }
        else
        {
            qbdsCustInvoiceTrans.addRange(fieldNum(CustInvoiceTrans, ItemId)).value(queryValue(_salesLine.ItemId));
        }
    }
}

/// <summary>
/// assig return values
/// </summary>
/// <param name = "_priceComponent">METSalesLinePriceComponent</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_tmpTable">METSalesLinePriceComponentTmp</param>
public void setValues(METSalesLinePriceComponent _priceComponent,
                  SalesLine _salesLine,
                  METSalesLinePriceComponentTmp _tmpTable,
                  SalesLine _orgSalesLine)
{
    real convFactor = 1;
    PdsCWUnitId pdsCWUnitId = _salesLine.pdsCWUnitId();

    if (!pdsCWUnitId && _orgSalesLine.SalesUnit !=  _salesLine.SalesUnit)
    {
        convFactor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesLine.itemId,
                                                                        _salesLine.InventDimId,
                                                                        1,
                                                                        _orgSalesLine.SalesUnit,
                                                                        _salesLine.SalesUnit,
                                                                        NoYes::Yes);
        _tmpTable.Value = convFactor ? -1 * CurrencyExchange::round((_priceComponent.Value / convFactor), _salesLine.CurrencyCode) : -1 * (_priceComponent.Value);
    }
    else
    {
        _tmpTable.Value = -1 * _priceComponent.Value;
    }

    SalesQty quantity;

    if (pdsCWUnitId)
    {
        quantity = SalesParmLine::isCWClaimCreditApplicable(_salesLine) ? _salesLine.metSalesLine().CWReturnWeight : _salesLine.PdsCWExpectedRetQty;
    }
    else
    {
        quantity = _salesLine.ExpectedRetQty;
    } 

    _tmpTable.ExtValue = -1 * (_tmpTable.Value * (quantity));
}
